next = [];
url = result[0];
length = result.length;
p = src.match(/page-link[^<]*>1\/(\d+)/)||[];
page = Number(p[1])||1;
maxPg = 200;
endPg = Math.min(page,maxPg);
if(length < endPg){
	for(i = 2; i <= endPg; i++){
		link = String(url).replace(/_\d+/,`_${i}`);
		next.push(link)
		}
		next;
	}else result

