@js: 
var id = baseUrl.match(/book\/(.*?)\.html/)[1];
java.put("id",id);
aid = `[data-aid="${id}"]@option||[data-aid="${id}"]@li`
var pages = java.getElements(aid);

java.log(pages.length)
if (pages.length==0) {
	so = java.ajax(baseUrl.replace(/book/,"chapter"));
java.setContent(so);
pages = java.getElements(aid);
	}

java.put("page",pages.length);
result = source.key + "/index.php?action=loadChapterPage" + "," + JSON.stringify({
  "body": `id=${id}&page=1`,
  "method": "POST"
});

ruleToc.chapterList:
$.data[*]
<js>
result=result
aa=/\{.*?"chapterorder":"(\d+)".*?\}/g
li=[]
let match
while ((match = aa.exec(result)) !== null) {
  li.push({
    id: parseInt(match[1], 10),
    content: match[0]
  });
}
li.sort((a, b) => a.id - b.id)
//java.log(JSON.stringify(li))
so=li.map(item => item.content).join(',')
s=so.replace(/^/,'{"list":[').replace(/$/,']}')
s
</js>$.list[*]

ruleToc.nextTocUrl:
@js: result = []
id = java.get("id");
pages = java.get("page");
java.log(pages)
for (let i = 2 ; i <= pages ; i++) {
option = source.key + "/index.php?action=loadChapterPage" + "," + JSON.stringify({
  "body": `id=${id}&page=${i}`,
  "method": "POST"
});
result.push(option);
}
result;

